import{_ as a,c as l,o as e,b0 as t}from"./chunks/framework.CLL9SSSf.js";const o="/linux-driver-docs/assets/005_i2c_hardware_connect.AogEEp-W.png",A="/linux-driver-docs/assets/006_teacher_and_student.ByrSAlnI.png",r="/linux-driver-docs/assets/009_i2c_signal.Bo6Lrfpp.png",s="/linux-driver-docs/assets/i2c002.CyGOt1wv.png",p="/linux-driver-docs/assets/i2c003.CKpPdA0t.png",c="/linux-driver-docs/assets/i2c004.B1FS6Ild.png",n="/linux-driver-docs/assets/007_i2c_write.UEOFR4sl.png",u="/linux-driver-docs/assets/008_i2c_read.BYz_ku5a.png",d="/linux-driver-docs/assets/i2c005.C9yf6BSF.png",C="/linux-driver-docs/assets/i2c006.CeAAIG_H.png",m="/linux-driver-docs/assets/i2c007.Csm-7Qgy.png",g="/linux-driver-docs/assets/i2c008.CQs2IZQO.png",S="/linux-driver-docs/assets/010_i2c_signal_internal.CJkmO-_m.png",h="data:image/png;base64,",x=JSON.parse('{"title":"LV005-I2C协议简介","description":null,"frontmatter":{"title":"LV005-I2C协议简介","date":"2026-01-21T17:12:12.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/kdriver/drv-i2c/126d2d53550c0a6879e9d905","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-21T17:12:12.166Z","fulluuid":"879e9d90597c4c80924b6ffe3b82a255","useduuid":"879e9d905"}},"headers":[],"relativePath":"sdoc/kdriver/drv-i2c/126d2d53550c0a6879e9d905.md","filePath":"sdoc/07-设备驱动子系统/07-i2c/LV005-I2C协议简介.md","lastUpdated":1769002717000}'),I={name:"sdoc/kdriver/drv-i2c/126d2d53550c0a6879e9d905.md"};function Q(B,i,b,k,D,E){return e(),l("div",null,[...i[0]||(i[0]=[t('<h1 id="lv005-i2c协议简介" tabindex="-1">LV005-I2C协议简介 <a class="header-anchor" href="#lv005-i2c协议简介" aria-label="Permalink to &quot;LV005-I2C协议简介&quot;">​</a></h1><p>了解下 I2C 协议。若笔记中有错误或者不合适的地方，欢迎批评指正 😃。</p><blockquote><p>可以参考这个文档：<a href="https://www.nxp.com/docs/en/user-guide/UM10204.pdf" target="_blank" rel="noreferrer">I2C-bus specification and user manual</a></p></blockquote><h2 id="一、硬件连接" tabindex="-1">一、硬件连接 <a class="header-anchor" href="#一、硬件连接" aria-label="Permalink to &quot;一、硬件连接&quot;">​</a></h2><p>I2C 在硬件上的接法如下所示，主控芯片引出两条线 SCL，SDA 线，在一条 I2C 总线上可以接很多 I2C 设备，我们还会放一个上拉电阻（放一个上拉电阻的原因以后我们再说）。</p><img src="'+o+'" alt="image-20210220144722044" style="zoom:67%;"><p>i2c 支持一主多从，各设备地址独立，标准模式传输速率为 100kbit/s，快速模式为 400kbit/s。总线通过上拉电阻接到电源。当 I2C 设备空闲时，会输出高阻态，而当所有设备都空 闲，都输出高阻态时，由上拉电阻把总线拉成高电平。2C 物理总线使用两条总线线路，SCL 和 SDA。</p><ul><li>SCL： 时钟线，数据收发同步</li><li>SDA： 数据线，传输具体数据</li></ul><h2 id="二、怎么传输数据" tabindex="-1">二、怎么传输数据？ <a class="header-anchor" href="#二、怎么传输数据" aria-label="Permalink to &quot;二、怎么传输数据？&quot;">​</a></h2><h3 id="_1-发球的例子" tabindex="-1">1. 发球的例子 <a class="header-anchor" href="#_1-发球的例子" aria-label="Permalink to &quot;1. 发球的例子&quot;">​</a></h3><p>怎么通过 I2C 传输数据？我们需要把数据从主设备发送到从设备上去，也需要把数据从从设备传送到主设备上去，数据涉及到双向传输。举个例子，现在我们上体育课，我们的体育老师可以把球发给学生，也可以把球从学生中接过来。</p><img src="'+A+'" alt="image-20210220145618978" style="zoom:50%;"><ul><li>发球：体育老师 → 学生</li></ul><p>（1）老师：开始了(start)</p><p>（2）老师：A！我要发球给你！(地址/方向)</p><p>（3）学生 A：到！(回应)</p><p>（4）老师把球发出去（传输）</p><p>（5）A 收到球之后，应该告诉老师一声（回应）</p><p>（6）老师：结束（停止）</p><ul><li>接球：学生 → 体育老师</li></ul><p>（1）老师：开始了(start)</p><p>（2）老师：B！把球发给我！(地址/方向)</p><p>（3）学生 B：到！</p><p>（4）B 把球发给老师（传输）</p><p>（5）老师收到球之后，给 B 说一声，表示收到球了（回应）</p><p>（6）老师：结束（停止）</p><h3 id="_2-i2c-的信号" tabindex="-1">2. I2C 的信号 <a class="header-anchor" href="#_2-i2c-的信号" aria-label="Permalink to &quot;2. I2C 的信号&quot;">​</a></h3><p>我们就使用上面这个简单的例子，来了解一下 IIC 的传输协议：</p><ul><li>老师说开始了，表示开始信号(start)</li><li>老师提醒某个学生要发球，表示发送地址和方向(address/read/write)</li><li>老师发球/接球，表示数据的传输</li><li>收到球要回应：回应信号(ACK)</li><li>老师说结束，表示 IIC 传输结束(P)</li></ul><p>下面我们回到 I2C 中，I2C 协议中数据传输的单位是字节，也就是 8 位。但是要用到 9 个时钟：前面 8 个时钟用来传输 8 数据，第 9 个时钟用来传输回应信号。传输时，先传输最高位(MSB)。I2C 协议信号应该是在每个 I2C 器件的芯片手册中都有，我们找一个看一下：</p><img src="'+r+'" alt="image-20210220151524099"><h4 id="_2-1-起始信号与结束信号" tabindex="-1">2.1 起始信号与结束信号 <a class="header-anchor" href="#_2-1-起始信号与结束信号" aria-label="Permalink to &quot;2.1 起始信号与结束信号&quot;">​</a></h4><ul><li>开始信号（S）：SCL 为高电平时，SDA 山高电平向低电平跳变，开始传送数据。</li><li>结束信号（P）：SCL 为高电平时，SDA 由低电平向高电平跳变，结束传送数据。</li></ul><img src="'+s+'" alt="3|"><p>当 SCL 线为高电平时，SDA 线由高到低的下降沿，为传输开始标志(S)。直到主设备发出结束信号(P)， 否则总线状态一直为忙。结束标志(P)为，当 SCL 线为高电平时，SDA 线由低到高的上升沿。</p><h4 id="_2-2-数据格式与应答信号-ack-nack" tabindex="-1">2.2 数据格式与应答信号(ACK/NACK) <a class="header-anchor" href="#_2-2-数据格式与应答信号-ack-nack" aria-label="Permalink to &quot;2.2 数据格式与应答信号(ACK/NACK)&quot;">​</a></h4><ul><li>应答信号(ACK)：接收器在接收到 8 位数据后，在第 9 个时钟周期，拉低 SDA</li><li>SDA 上传输的数据必须在 SCL 为高电平期间保持稳定，SDA 上的数据只能在 SCL 为低电平期间变化</li></ul><img src="'+p+'" alt="3|" style="zoom:80%;"><p>i2c 的数据字节定义为 8-bits 长度，对每次传送的总字节数量没有限制, 但对每一次传输必须伴有一个应答(ACK)信号， 其时钟由主设备提供，而真正的应答信号由从设备发出，在时钟为高时，通过拉低并保持 SDA 的值来实现。如果从设备忙， 它可以使 SCL 保持在低电平，这会强制使主设备进入等待状态。当从设备空闲后，并且释放时钟线，原来的数据传输才会继续。3</p><h4 id="_2-3-主机与从机通信" tabindex="-1">2.3 主机与从机通信 <a class="header-anchor" href="#_2-3-主机与从机通信" aria-label="Permalink to &quot;2.3 主机与从机通信&quot;">​</a></h4><p>完整的通信过程时序大概如下图：</p><img src="'+c+'" alt="3|" style="zoom:80%;"><p>开始标志(S)发出后，主设备会传送一个 7 位的 Slave 地址，并且后面跟着一个第 8 位，称为 Read/Write 位。 R/W 位表示主设备是在接受从设备的数据还是在向其写数据。然后，主设备释放 SDA 线，等待从设备的应答信号(ACK)。 每个字节的传输都要跟随有一个应答位。应答产生时，从设备将 SDA 线拉低并且在 SCL 为高电平时保持低。 数据传输总是以停止标志（P）结束，然后释放通信线路。 然而，主设备也可以产生重复的开始信号去操作另一台从设备， 而不发出结束标志。综上可知，所有的 SDA 信号变化都要在 SCL 时钟为低电平时进行，除了开始和结束标志</p><h2 id="三、i2c-传输数据的格式" tabindex="-1">三、I2C 传输数据的格式 <a class="header-anchor" href="#三、i2c-传输数据的格式" aria-label="Permalink to &quot;三、I2C 传输数据的格式&quot;">​</a></h2><h3 id="_1-写操作" tabindex="-1">1. 写操作 <a class="header-anchor" href="#_1-写操作" aria-label="Permalink to &quot;1. 写操作&quot;">​</a></h3><p>流程如下：</p><ul><li>主芯片要发出一个 start 信号</li><li>然后发出一个设备地址(用来确定是往哪一个芯片写数据)，方向(读/写，0 表示写，1 表示读)</li><li>从设备回应(用来确定这个设备是否存在)，然后就可以传输数据</li><li>主设备发送一个字节数据给从设备，并等待回应</li><li>每传输一字节数据，接收方要有一个回应信号（确定数据是否接受完成)，然后再传输下一个数据。</li><li>数据发送完之后，主芯片就会发送一个停止信号。</li></ul><p>下图中白色背景表示 &quot;主→ 从&quot;，灰色背景表示 &quot;从→ 主&quot;</p><img src="'+n+'" alt="image-20210220150757825" style="zoom:60%;"><h3 id="_2-读操作" tabindex="-1">2. 读操作 <a class="header-anchor" href="#_2-读操作" aria-label="Permalink to &quot;2. 读操作&quot;">​</a></h3><p>流程如下：</p><ul><li><p>主芯片要发出一个 start 信号</p></li><li><p>然后发出一个设备地址(用来确定是往哪一个芯片写数据)，方向(读/写，0 表示写，1 表示读)</p></li><li><p>从设备回应(用来确定这个设备是否存在)，然后就可以传输数据</p></li><li><p>从设备发送一个字节数据给主设备，并等待回应</p></li><li><p>每传输一字节数据，接收方要有一个回应信号（确定数据是否接受完成)，然后再传输下一个数据。</p></li><li><p>数据发送完之后，主芯片就会发送一个停止信号。</p></li></ul><p>下图中白色背景表示 &quot;主→ 从&quot;，灰色背景表示 &quot;从→ 主&quot;</p><img src="'+u+'" alt="image-20210220150954993" style="zoom:60%;"><h3 id="_3-读写实例" tabindex="-1">3. 读写实例 <a class="header-anchor" href="#_3-读写实例" aria-label="Permalink to &quot;3. 读写实例&quot;">​</a></h3><p>我们来看一下 i2c 对 mpu6050 进行数据读写的流程。</p><ul><li>单字节写入</li></ul><img src="'+d+'" alt="3|"><ul><li>连续字节写入</li></ul><img src="'+C+'" alt="3|" style="zoom:82%;"><p>对 MPU6050 进行写操作时，主设备发出开始标志(S)和写地址(地址位加一个 R/W 位，0 为写)。 MPU6050 产生应答信号。然后主设备开始传送寄存器地址(RA)，接到应答后，开始传送寄存器数据， 然后仍然要有应答信号，连续写入多字节时依次类推。</p><ul><li>单字节读出</li></ul><img src="'+m+'" alt="3|" style="zoom:82%;"><ul><li>连续字节读出</li></ul><img src="'+g+'" alt="3|" style="zoom:82%;"><p>对 MPU6050 进行读操作时，主设备发出开始标志(S)和读地址(地址位加一个 R/W 位，1 为读)。 等待 MPU6050 产生应答信号。然后发送寄存器地址，告诉 MPU6050 读哪一个寄存器。 紧接着，收到应答信号后，主设备再发一个开始信号，然后发送从设备读地址。 MPU6050 产生应答信号并开始发送寄存器数据。通信以主设备产生的拒绝应答信号(NACK)和结束标志(P)结束。</p><h3 id="_4-协议细节" tabindex="-1">4. 协议细节 <a class="header-anchor" href="#_4-协议细节" aria-label="Permalink to &quot;4. 协议细节&quot;">​</a></h3><ul><li>如何在 SDA 上实现双向传输？</li></ul><p>主芯片通过一根 SDA 线既可以把数据发给从设备，也可以从 SDA 上读取数据，连接 SDA 线的引脚里面必然有两个引脚（发送引脚/接受引脚）。</p><ul><li>主、从设备都可以通过 SDA 发送数据，肯定不能同时发送数据，怎么错开时间？</li></ul><p>在 9 个时钟里，前 8 个时钟由主设备发送数据的话，第 9 个时钟就由从设备发送数据；前 8 个时钟由从设备发送数据的话，第 9 个时钟就由主设备发送数据。</p><ul><li>双方设备中，某个设备发送数据时，另一方怎样才能不影响 SDA 上的数据？（为什么 SDA 上要有上拉电阻？）</li></ul><p>设备的 SDA 中有一个三极管，使用开极/开漏电路(三极管是开极，CMOS 管是开漏，作用一样)，如下图：</p><img src="'+S+'" alt="image-20210220152057547" style="zoom:50%;"><p>真值表如下：</p><img src="'+h+'" alt="image-20210220152134970" style="zoom:50%;"><p>从真值表和电路图我们可以知道：</p><p>（1）当某一个芯片不想影响 SDA 线时，那就不驱动这个三极管</p><p>（2）想让 SDA 输出高电平，双方都不驱动三极管(SDA 通过上拉电阻变为高电平)</p><p>（3）想让 SDA 输出低电平，就驱动三极管</p><p>可以看个例子，了解下数据是怎么传的（实现双向传输）。主设备发送（8bit）给从设备</p><p>前 8 个 clk：从设备不要影响 SDA，从设备不驱动三极管。主设备决定数据，主设备要发送 1 时不驱动三极管，要发送 0 时驱动三极管</p><p>第 9 个 clk：由从设备决定数据，主设备不驱动三极管。从设备决定数据，要发出回应信号的话，就驱动三极管让 SDA 变为 0。从这里也可以知道 ACK 信号是低电平。</p><p>从上面的这个例子，就可以知道怎样在一条线上实现双向传输，这就是 SDA 上要使用 <strong>上拉电阻的原因</strong>。</p><ul><li>为何 SCL 也要使用上拉电阻？</li></ul><p>在第 9 个时钟之后，如果有某一方需要更多的时间来处理数据，它可以一直驱动三极管把 SCL 拉低。当 SCL 为低电平时候，大家都不应该使用 I2C 总线，只有当 SCL 从低电平变为高电平的时候，IIC 总线才能被使用。当它就绪后，就可以不再驱动三极管，这是上拉电阻把 SCL 变为高电平，其他设备就可以继续使用 I2C 总线了。</p><ul><li>对于 IIC 协议它只能规定怎么传输数据，数据是什么含义由从设备决定。</li></ul>',87)])])}const L=a(I,[["render",Q]]);export{x as __pageData,L as default};
